{"cards": [{"node_code": "N_92042de0e3a25a0a", "definition": "研究制造过程中原材料、能源及辅助介质的节约与高效利用技术，旨在降低资源消耗并提升制造过程的资源效率。", "boundary": "聚焦于制造环节的资源输入端优化，包括材料利用率提升、机床及工厂能效管理、水与公用工程优化。边界在于关注“资源投入的效率”，不涉及污染物排放治理（归入“清洁生产与排放控制”）或产品全生命周期评价（归入“循环制造与可持续评价”）。", "includes": ["材料利用率提升、近净成形及减量化设计在制造中的应用", "机床、工艺装备及工厂层面的能效监测、优化与节能技术", "冷却水、压缩空气等辅助介质及公用工程系统的优化管理"], "excludes": ["制造过程产生的废气、废水、噪声等污染物的治理技术", "产品报废后的回收处理或全生命周期碳足迹评价"], "sibling_distinctions": [{"other_code": "N_d2479324da83c3b7", "rule": "本节点关注“少用”（资源/能源节约），兄弟节点关注“少排”（污染物控制与治理）。"}, {"other_code": "N_7bef9d1b2e3530f1", "rule": "本节点关注制造过程中的即时资源效率，兄弟节点关注产品全生命周期的循环性与综合可持续性评价。"}], "cross_boundary_rule": "若研究重点在于通过工艺参数优化降低单位产品能耗，主挂载本节点；若重点在于能耗数据的采集与工厂整体调度优化，可关联“生产系统规划与运行”，但资源效率指标本身归本节点。"}, {"node_code": "N_d2479324da83c3b7", "definition": "研究制造过程中污染物的源头削减、过程控制及末端治理技术，以及清洁生产工艺的替代方案，以实现环境友好型制造。", "boundary": "聚焦于制造活动产生的环境负荷控制，涵盖切削液/清洗剂管理、废气废水粉尘噪声治理及低碳工艺替代。边界在于关注“污染物的产生与控制”，不涉及资源节约（归入“资源与能源高效制造”）或产品回收再利用（归入“循环制造与可持续评价”）。", "includes": ["切削液、清洗剂等有害物质的替代、回收及过程控制", "制造过程产生的废气、废水、粉尘、噪声的治理技术与设备", "清洁生产工艺、低碳制造过程替代方案及绿色工艺开发"], "excludes": ["不涉及制造过程背景的通用环保设施设计或环境科学理论", "产品使用阶段的能耗管理或报废后的拆解回收技术"], "sibling_distinctions": [{"other_code": "N_92042de0e3a25a0a", "rule": "本节点关注“污染控制”（排放治理），兄弟节点关注“资源效率”（投入节约）。"}, {"other_code": "N_7bef9d1b2e3530f1", "rule": "本节点关注制造过程中的即时污染控制，兄弟节点关注产品全生命周期的循环设计与综合绩效评价。"}], "cross_boundary_rule": "若研究涉及切削液既作为资源节约（减少用量）又作为污染物控制（减少排放），若侧重工艺参数对排放的影响，主挂载本节点；若侧重用量优化带来的成本与资源节约，主挂载“资源与能源高效制造”。"}, {"node_code": "N_7bef9d1b2e3530f1", "definition": "研究制造系统的循环经济模式、产品再制造技术及制造过程全生命周期的环境与社会可持续性评价方法。", "boundary": "聚焦于制造系统的闭环特性与综合绩效评价，涵盖再利用/再制造、闭环生产系统及生命周期评价（LCA）。边界在于关注“循环性与综合可持续性”，不涉及制造过程中的即时资源节约（归入“资源与能源高效制造”）或即时污染控制（归入“清洁生产与排放控制”）。", "includes": ["产品再利用、再制造工艺及闭环生产系统设计", "制造过程生命周期评价（LCA）、碳足迹分析及可持续性指标体系", "面向可持续性的制造系统规划与逆向物流集成"], "excludes": ["不涉及制造背景的通用循环经济理论或社会经济学研究", "单纯的制造过程能效优化或污染物治理技术（除非作为LCA输入数据）"], "sibling_distinctions": [{"other_code": "N_92042de0e3a25a0a", "rule": "本节点关注“循环与评价”（全生命周期视角），兄弟节点关注“效率”（制造过程即时视角）。"}, {"other_code": "N_d2479324da83c3b7", "rule": "本节点关注“系统循环与综合绩效”，兄弟节点关注“过程污染控制”。"}], "cross_boundary_rule": "若研究旨在通过LCA方法评估某项节能技术的环境效益，主挂载本节点；若研究旨在开发该节能技术本身，主挂载“资源与能源高效制造”。"}]}
